import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@^3.25.76";
var get_contact_default = defineTool2({
  name: "get_contact",
  title: "Get contact detail",
  description: "Fetch one contact's full record plus its most recent call logs and notes. Use search_contacts first to find the contact ID.",
  inputSchema: {
    contact_id: z2.string().uuid().describe("The contact's UUID.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ contact_id }, ctx) => {
    if (!requireUser(ctx)) return unauthenticated();
    const supabase = supabaseForUser(ctx);
    const { data: contact, error } = await supabase.from("contacts").select("*").eq("id", contact_id).maybeSingle();
    if (error) return failure(error.message);
    if (!contact) return failure("No contact found with that ID (or you do not have access to it).");
    const [{ data: calls }, { data: notes }] = await Promise.all([
      supabase.from("call_logs").select("id, outcome, notes, created_at, dialpad_talk_time_seconds, follow_up_date").eq("contact_id", contact_id).order("created_at", { ascending: false }).limit(10),
      supabase.from("contact_notes").select("id, content, source, created_at").eq("contact_id", contact_id).order("created_at", { ascending: false }).limit(10)
    ]);
    return json(
      { contact, recent_calls: calls ?? [], recent_notes: notes ?? [] },
      { contact_id }
    );
  }
});

// src/lib/mcp/tools/my-call-activity.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z3 } from "npm:zod@^3.25.76";
var my_call_activity_default = defineTool3({
  name: "my_call_activity",
  title: "My call activity",
  description: "Summarise the signed-in rep's own call activity over the last N days: total dials, a breakdown by outcome, and total talk time.",
  inputSchema: {
    days: z3.number().int().min(1).max(90).optional().describe("Look-back window in days (default 7).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ days }, ctx) => {
    const userId = requireUser(ctx);
    if (!userId) return unauthenticated();
    const window = days ?? 7;
    const since = new Date(Date.now() - window * 24 * 60 * 60 * 1e3).toISOString();
    const supabase = supabaseForUser(ctx);
    const { data, error } = await supabase.from("call_logs").select("outcome, created_at, dialpad_talk_time_seconds").eq("user_id", userId).gte("created_at", since).limit(5e3);
    if (error) return failure(error.message);
    const rows = data ?? [];
    const byOutcome = {};
    let talkSeconds = 0;
    for (const row of rows) {
      byOutcome[row.outcome] = (byOutcome[row.outcome] ?? 0) + 1;
      talkSeconds += row.dialpad_talk_time_seconds ?? 0;
    }
    return json({
      window_days: window,
      total_dials: rows.length,
      by_outcome: byOutcome,
      total_talk_minutes: Math.round(talkSeconds / 60)
    });
  }
});

